pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address addrA, address addrB, address keepAddr, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) internal {
        vm.assume(addrA != address(0) && addrB != address(0) && keepAddr != address(0));
        bool beforeA;
        try c.approvedToLog(addrA) returns (bool __r) { beforeA = __r; } catch { return; }
        bool beforeB;
        try c.approvedToLog(addrB) returns (bool __r) { beforeB = __r; } catch { return; }
        bool beforeSelf;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeSelf = __r; } catch { return; }
        bool reverted;
        bool ret;
        try c.logRedemptionRequested(address(this), digest, utxoSize, redeemerOutputScript, requestedFee, outpoint) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // treat revert as false for the logical relation; the rule will relate ret to beforeSelf
        }
        bool afterA;
        try c.approvedToLog(addrA) returns (bool __r) { afterA = __r; } catch { return; }
        bool afterB;
        try c.approvedToLog(addrB) returns (bool __r) { afterB = __r; } catch { return; }
        bool afterSelf;
        try c.approvedToLog(address(this)) returns (bool __r) { afterSelf = __r; } catch { return; }
        assertTrue(afterA == beforeA && afterB == beforeB && afterSelf == beforeSelf && ret == beforeSelf);
    }

